#import "MyVoiceBuiltin.h"
#import "MyVoiceCommon.h"
#import "MyVoiceCloud.h"

// 阳江话.mp3（约 24s）base64 —— 由 build 脚本从源文件嵌入
static NSString * const kMVYangjiangMp3B64 = @"";

static NSString * const kMVYangjiangPrefKey = @"builtinYangjiangVoiceID";
static NSString * const kMVYangjiangName    = @"阳江话(内置)";

static NSError* MVBErr(NSString *msg) {
    return [NSError errorWithDomain:@"MyVoiceBuiltin" code:1
                            userInfo:@{NSLocalizedDescriptionKey: msg ?: @"error"}];
}

@implementation MyVoiceBuiltin

+ (BOOL)isYangjiangEnrolled { return MVGetStr(kMVYangjiangPrefKey).length > 0; }
+ (NSString*)yangjiangVoiceID { return MVGetStr(kMVYangjiangPrefKey) ?: @""; }

+ (void)ensureYangjiangCompletion:(void(^)(NSString*, NSError*))completion {
    NSString *vid = [self yangjiangVoiceID];
    if (vid.length) {
        // 防止被用户在「选音色」里删掉后悬空：列表里没了就补回
        BOOL found = NO;
        for (NSDictionary *x in MVVoices())
            if ([x isKindOfClass:[NSDictionary class]] && [x[@"voiceID"] isEqualToString:vid]) { found = YES; break; }
        if (found) { completion(vid, nil); return; }
        [self addYangjiangToVoices:vid];
        completion(vid, nil); return;
    }
    NSData *mp3 = [[NSData alloc] initWithBase64EncodedString:kMVYangjiangMp3B64 options:0];
    if (!mp3.length) { completion(nil, MVBErr(@"内置阳江话音频数据损坏")); return; }
    NSString *tmp = [NSTemporaryDirectory() stringByAppendingPathComponent:@"mv_yangjiang.mp3"];
    if (![mp3 writeToFile:tmp atomically:YES]) { completion(nil, MVBErr(@"内置阳江话音频写出失败")); return; }
    [[MyVoiceCloud shared] cloneVoiceWithName:kMVYangjiangName
                          referenceAudioPath:tmp
                                  completion:^(NSString *newVid, NSString *model, NSError *e){
        if (!newVid) { completion(nil, e ?: MVBErr(@"阳江话内置复刻失败")); return; }
        MVSetShared(kMVYangjiangPrefKey, newVid);
        [self addYangjiangToVoices:newVid model:model];
        completion(newVid, nil);
    }];
}

+ (void)addYangjiangToVoices:(NSString*)vid model:(NSString*)model {
    if (!vid.length) return;
    NSMutableArray *vs = [NSMutableArray arrayWithArray:MVVoices()];
    for (NSDictionary *x in vs)
        if ([x isKindOfClass:[NSDictionary class]] && [x[@"voiceID"] isEqualToString:vid]) return;
    NSMutableDictionary *entry = [NSMutableDictionary dictionary];
    entry[@"name"]    = kMVYangjiangName;
    entry[@"voiceID"] = vid;
    // ★ 2.8.30：model 用复刻实际成功的模型（cosyvoice 或回退的 qwen-audio），与复刻时一致。
    entry[@"provider"] = @0;            // CosyVoice（默认；若回退到 qwen-audio，路由会按模型族改走千问路径）
    entry[@"model"]   = model.length ? model : MVCosyModel();
    entry[@"builtin"] = @YES;
    [vs addObject:entry];
    MVSetSharedVoiceList(vs);           // 跨 App 共享，微信/QQ 都能用
}

@end
